/**
 * NovaKit Lite — design tokens.
 * These are the shared vocabulary every screen should build from.
 */
export default {
  content: ["./index.html", "./src/**/*.{js,jsx}"],
  theme: {
    extend: {
      colors: {
        // Brand — indigo, with a full tint ramp for surfaces, hovers and emphasis.
        brand: {
          50: "#EEF2FF",
          100: "#E0E7FF",
